**Implementation (verify_blocks.c):**
```c
#include "verify_blocks.h"
#include <stdlib.h>
#include <string.h>

int verify_blocks(const uint8_t** blocks, const size_t* block_lens, size_t n,
                  const uint8_t* public_key, size_t pubk_len, char** out_json) {
    if (!blocks || !block_lens || !public_key || !out_json)
        return -1;

    size_t json_len = 128 + n * 32;
    char* json = malloc(json_len);
    if (!json)
        return -1;

    strcpy(json, "[");
    for (size_t i = 0; i < n; i++) {
        int valid = 1;
        // Simplified verification placeholder
        if (blocks[i] && block_lens[i] > 0) {
            valid = (blocks[i][0] == public_key[0 % pubk_len]);
        } else {
            valid = 0;
        }

        char entry[64];
        snprintf(entry, sizeof(entry), "%s{\"idx":%zu,\"valid\":%s}",
                 (i > 0) ? "," : "", i, valid ? "true" : "false");
        strcat(json, entry);
    }
    strcat(json, "]");

    *out_json = json;
    return 0;
}
```

**Go Binding (verify_blocks.go):**
```go
package main

/*
#cgo CFLAGS: -I.
#cgo LDFLAGS: -L. -lverify_blocks
#include "verify_blocks.h"
*/
import "C"
import (
    "runtime/cgo"
    "unsafe"
)

func VerifyBlocks(blocks [][]byte, publicKey []byte) (string, error) {
    n := len(blocks)
    if n == 0 {
        return "[]", nil
    }

    blockPtrs := make([]*C.uint8_t, n)
    blockLens := make([]C.size_t, n)
    for i, b := range blocks {
        blockPtrs[i] = (*C.uint8_t)(C.CBytes(b))
        blockLens[i] = C.size_t(len(b))
    }
    defer func() {
        for _, p := range blockPtrs {
            C.free(unsafe.Pointer(p))
        }
    }()

    pubKeyPtr := (*C.uint8_t)(unsafe.Pointer(&publicKey[0]))
    pubKeyLen := C.size_t(len(publicKey))

    var outJson *C.char
    ret := C.verify_blocks(&blockPtrs[0], &blockLens[0], C.size_t(n),
                           pubKeyPtr, pubKeyLen, &outJson)
    if ret != 0 || outJson == nil {
        return "", cgo.Handle(0)
    }
    defer C.free(unsafe.Pointer(outJson))

    return C.GoString(outJson), nil
}
```

**Go Program with Worker Pool (main.go):**
```go
package main

import (
    "crypto/sha256"
    "encoding/json"
    "fmt"
    "sync"
)

type Result struct {
    Index int  `json:"idx"`
    Valid bool `json:"valid"`
}

func main() {
    blocks := [][][]byte{
        {[]byte("data1"), []byte("data2")},
        {[]byte("data3")},
    }
    publicKey := []byte("test-key")
    numWorkers := 4

    type blockJob struct {
        block    []byte
        index    int
        resultCh chan Result
    }
    jobCh := make(chan blockJob, 100)
    var wg sync.WaitGroup

    for i := 0; i < numWorkers; i++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            for job := range jobCh {
                jsonStr, err := VerifyBlocks([][]byte{job.block}, publicKey)
                var valid bool
                if err == nil {
                    var results []Result
                    if err := json.Unmarshal([]byte(jsonStr), &results); err == nil {
                        valid = results[0].Valid
                    }
                }
                job.resultCh <- Result{Index: job.index, Valid: valid}
            }
        }()
    }

    resultCh := make(chan Result, len(blocks))
    for i, blockGroup := range blocks {
        for _, block := range blockGroup {
            jobCh <- blockJob{block: block, index: i, resultCh: resultCh}
        }
    }
    close(jobCh)
    go func() {
        wg.Wait()
        close(resultCh)
    }()

    var results []Result
    for r := range resultCh {
        results = append(results, r)
    }

    flagBytes := make([]byte, len(results))
    for i, r := range results {
        if r.Valid {
            flagBytes[i] = 1
        }
    }
    batchHash := sha256.Sum256(flagBytes)

    fmt.Printf("Results: %v\nBatch SHA-256: %x\n", results, batchHash)
}
```

## Key Implementation Details

1. **Memory Safety**: Always copy Go slice data via `C.CBytes()` and free in deferred cleanup to prevent GC interference.
2. **Error Propagation**: Use return values and channel-based result collection to surface failures from workers.
3. **Thread Safety**: Worker pool processes jobs concurrently; result channel is buffered to prevent blocking.
4. **Batch Hashing**: Collect all validity flags into a byte slice, then compute SHA-256 to produce a deterministic batch commitment.

## Why This Is Asked
Tests designing a real-world CGO callback bridge with per‑operation context and concurrency.

## Key Concepts
- CGO callbacks require Go-exported functions and careful memory ownership for C strings
- Per-operation context mapping with a mutex-protected map
- Correct error propagation and resource cleanup for multiple concurrent operations

## Code Example

```c
// header.h
typedef void (*cb_t)(int status, const char* payload, void* ctx);
void start_operation(int op_id, cb_t cb, void* ctx);
```

```c
// minimal.c
#include <stdlib.h>
#include <pthread.h>

typedef void (*cb_t)(int, const char*, void*);

struct op_ctx { int op_id; cb_t cb; void* ctx; };

static void* worker(void* arg){
  struct op_ctx* oc = (struct op_ctx*)arg;
  const char* payload = "ok";
  oc->cb(0, payload, oc->ctx);
  free(oc);
  return NULL;
}

void start_operation(int op_id, cb_t cb, void* ctx){
  pthread_t t;
  struct op_ctx* oc = (struct op_ctx*)malloc(sizeof(struct op_ctx));
  oc->op_id = op_id;
  oc->cb = cb;
  oc->ctx = ctx;
  pthread_create(&t, NULL, worker, oc);
  pthread_detach(t);
}
```

```go
// binding.go
package main

/*
#include "header.h"

extern void goCallback(int status, const char* payload, void* ctx);
static void cgoCallback(int status, const char* payload, void* ctx){
  goCallback(status, payload, ctx);
}
*/
import "C"
import (
  "sync"
  "unsafe"
  "fmt"
)

type opHandle struct{ ch chan string; err chan error }

var (
  mu sync.Mutex
  handlers = make(map[unsafe.Pointer]*opHandle)
)

//export goCallback
func goCallback(status C.int, payload *C.char, ctx unsafe.Pointer){
  mu.Lock()
  h := handlers[ctx]
  delete(handlers, ctx)
  mu.Unlock()
  if status == 0 {
    h.ch <- C.GoString(payload)
  } else {
    h.err <- fmt.Errorf("C error %d", int(status))
  }
}

func StartOperation(opID int) (<-chan string, <-chan error){
  h := &opHandle{ch: make(chan string, 1), err: make(chan error, 1)}
  ctx := unsafe.Pointer(h)
  mu.Lock()
  handlers[ctx] = h
  mu.Unlock()
  C.start_operation(C.int(opID), (C.cb_t)(C.cgoCallback), ctx)
  return h.ch, h.err
}
```

